import {test,expect} from '@playwright/test';
test('desktop home has complete imagery, links and no horizontal overflow',async({page})=>{const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('./');await expect(page.getByRole('heading',{name:/A place for art/})).toBeVisible();await page.locator('.hero-image img').evaluate(i=>i.decode());expect(await page.locator('.hero-image img').evaluate(i=>i.naturalWidth)).toBeGreaterThan(1000);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBeTruthy();expect(errors).toEqual([]);await page.screenshot({path:'test-results/home-desktop.png',fullPage:true});});
test('filters enforce all constraints and provide empty result recovery',async({page})=>{await page.goto('./#/art');await expect(page.locator('.art-card')).toHaveCount(6);await page.selectOption('#art-medium','Abstract');await page.selectOption('#art-budget','3000');await expect(page.locator('.art-card')).toHaveCount(0);await expect(page.getByRole('heading',{name:/give your search/})).toBeVisible();await page.getByRole('button',{name:'Clear filters ↺',exact:true}).click();await expect(page.locator('.art-card')).toHaveCount(6);await page.selectOption('#art-sort','high');await expect(page.locator('.art-card').first()).toContainText('Mesa light');});
test('saved plan persists and research pages never create checkout offers',async({page})=>{await page.goto('./#/art');await page.locator('.art-card').first().getByRole('button',{name:'Save to your plan'}).click();await page.goto('./#/plan');await expect(page.locator('.plan-item')).toHaveCount(1);await page.reload();await expect(page.locator('.plan-item')).toHaveCount(1);await page.goto('./#/artist/artist-1');await expect(page.locator('.source-work')).toHaveCount(6);await expect(page.getByRole('button',{name:'Preview purchase',exact:false})).toHaveCount(0);});
test('concierge applies visible filters and undo restores previous collection',async({page})=>{await page.goto('./#/art');await page.locator('#concierge-launch').click();await page.locator('#chat-input').fill('Show abstract works under $5,000');await page.locator('#chat-form').getByRole('button').click();await page.getByRole('button',{name:'Apply these filters ↗'}).click();await expect(page.locator('#concierge')).toBeHidden();await expect(page.locator('.art-card')).toHaveCount(2);await expect(page.locator('#art-medium')).toHaveValue('Abstract');await page.getByRole('button',{name:'Undo concierge filters'}).click();await expect(page.locator('.art-card')).toHaveCount(6);});
test('demonstration checkout changes total and confirms no charge or order',async({page})=>{await page.goto('./#/art/mesa-light');await page.getByRole('button',{name:'Preview purchase'}).click();await page.selectOption('#delivery','200');await expect(page.locator('#checkout-total')).toHaveText('$6,000');await page.locator('#demo-confirm').check();await page.getByRole('button',{name:'Complete the demonstration'}).click();await expect(page.locator('#modal')).toContainText('No payment was taken');await expect(page.locator('#modal')).toContainText('no order was sent');});
test('all venue sections, schematic and lodging date validation work',async({page})=>{await page.goto('./#/galleries');await expect(page.locator('.gallery-row')).toHaveCount(12);await page.goto('./#/experiences');await expect(page.locator('.place-card')).toHaveCount(10);await page.selectOption('#experience-type','Wellness');await expect(page.locator('.place-card')).toHaveCount(1);await page.getByRole('button',{name:'Map',exact:true}).click();await expect(page.locator('.map-panel')).toBeVisible();await page.goto('./#/eat-stay');await expect(page.locator('.hospitality-card')).toHaveCount(8);await page.getByRole('link',{name:'Stay (8)'}).click();await expect(page.locator('.hospitality-card')).toHaveCount(8);await page.goto('./#/place/hotel-willa');await page.getByRole('button',{name:'Check the booking next step'}).click();await expect(page.locator('#toast')).toContainText('Choose an arrival');await page.fill('#stay-arrival','2026-11-10');await page.fill('#stay-departure','2026-11-12');await page.getByRole('button',{name:'Check the booking next step'}).click();await expect(page.locator('#modal')).toContainText('No reservation has been made');});
test('phone navigation, dialog, chat focus and layouts stay usable',async({page})=>{await page.setViewportSize({width:390,height:844});await page.goto('./');await expect(page.getByRole('heading',{name:/A place for art/})).toBeVisible();await page.getByRole('button',{name:'Open navigation'}).click();await page.locator('#mobile-nav').getByRole('link',{name:'Art & artists'}).click();await expect(page.locator('.art-card')).toHaveCount(6);for(const path of ['/','/art','/galleries','/experiences','/eat-stay','/plan','/art/mesa-light']){await page.goto('./#'+path);await expect(page.locator('#main h1')).toBeVisible();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),path).toBeTruthy();}await page.goto('./');await page.screenshot({path:'test-results/home-phone.png',fullPage:true});await page.locator('#concierge-launch').click();await expect(page.locator('#chat-input')).toBeFocused();await page.keyboard.press('Escape');await expect(page.locator('#concierge')).toBeHidden();});

test('comparison keeps exact demo metadata and unsafe input stays text',async({page})=>{await page.goto('./#/art');await page.locator('.art-card').nth(0).getByRole('button',{name:'Compare ＋'}).click();await page.locator('.art-card').nth(1).getByRole('button',{name:'Compare ＋'}).click();await expect(page.locator('#modal')).toContainText('Two ways of seeing');await expect(page.locator('#modal')).toContainText('$5,800');await expect(page.locator('#modal')).toContainText('$4,200');await page.keyboard.press('Escape');await page.locator('#concierge-launch').click();await page.fill('#chat-input','<img src=x onerror="window.xss=true">');await page.locator('#chat-form').getByRole('button').click();expect(await page.evaluate(()=>window.xss)).toBeUndefined();await expect(page.locator('.chat-message.user').last()).toContainText('<img');});

test('Arroyo Seco travel origin updates and imported plan can be removed',async({page})=>{await page.goto('./#/experiences');await page.selectOption('#experience-origin','seco');await expect(page.locator('.place-card').first()).toContainText('from Arroyo Seco');await page.goto('./#/plan?items=mesa-light');await expect(page.locator('.plan-item')).toHaveCount(1);await page.locator('.plan-controls').getByRole('button',{name:'Remove Mesa light from plan'}).click();await expect(page.locator('.plan-item')).toHaveCount(0);await page.reload();await expect(page.locator('.plan-item')).toHaveCount(0);});
